-- Run only after r2_video_scaffold.sql + the new migration in a disposable DB.
begin;
create function pg_temp.assert_true(value boolean, label text) returns void language plpgsql as $$ begin if value is distinct from true then raise exception 'Assertion failed: %',label; end if; end $$;
create function pg_temp.must_fail(statement text) returns void language plpgsql as $$
declare failed boolean := false;
begin begin execute statement; exception when others then failed := true; end; if not failed then raise exception 'Expected rejection: %',statement; end if; end $$;

select pg_temp.assert_true((select video_source='legacy_youtube' and status='published' and youtube_video_id='dQw4w9WgXcQ' and mux_playback_id='historical-mux' from lessons where id='00000000-0000-4000-8000-000000000013'),'legacy lesson preserved');
