select pg_temp.must_fail($q$select validate_lesson_video('00000000-0000-4000-8000-000000000021','etag','{}')$q$);
update lesson_video_uploads set state='uploading', multipart_id='multipart' where id='00000000-0000-4000-8000-000000000031';
