select pg_temp.must_fail($q$select validate_lesson_video('00000000-0000-4000-8000-000000000021','etag','{"container":"mp4","video_codec":"hevc","audio_codec":"aac","pixel_format":"yuv420p","fast_start":true,"duration_seconds":300,"validation_version":"test"}')$q$);
select pg_temp.must_fail($q$select validate_lesson_video('00000000-0000-4000-8000-000000000021','etag','{}')$q$);
select validate_lesson_video('00000000-0000-4000-8000-000000000021','etag','{"container":"mp4","video_codec":"h264","audio_codec":"aac","pixel_format":"yuv420p","fast_start":true,"duration_seconds":300,"validation_version":"test"}');
