insert into lesson_progress(id,lesson_id,student_id,enrollment_id,progress_seconds,is_completed,completed_at,completion_percentage) values('00000000-0000-4000-8000-000000000061','00000000-0000-4000-8000-000000000011','00000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000051',37,true,now(),100);
