select pg_temp.assert_true((select progress_seconds=37 and is_completed from lesson_progress where id='00000000-0000-4000-8000-000000000061'),'replacement preserves progress');
update lesson_progress set is_completed=false, completed_at=null, completion_percentage=0 where id='00000000-0000-4000-8000-000000000061';
select pg_temp.assert_true((select is_completed and completed_at is not null and completion_percentage=100 from lesson_progress where id='00000000-0000-4000-8000-000000000061'),'completion sticky across writes');
