select pg_temp.must_fail($q$select attach_lesson_video('00000000-0000-4000-8000-000000000011','00000000-0000-4000-8000-000000000022','00000000-0000-4000-8000-000000000001',now())$q$);
select set_config('test.student','00000000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true(can_access_published_lesson('00000000-0000-4000-8000-000000000013'),'inclusive start');
update enrollments set expires_at=now();
