update courses set status='unpublished';
select pg_temp.assert_true(not can_access_published_lesson('00000000-0000-4000-8000-000000000013'),'unpublished parent blocked');
set local role authenticated;
select pg_temp.must_fail($q$select * from lesson_video_uploads$q$);
select pg_temp.must_fail($q$select validate_lesson_video('00000000-0000-4000-8000-000000000021','etag','{}')$q$);
select pg_temp.must_fail($q$update lessons set video_asset_id='00000000-0000-4000-8000-000000000021' where id='00000000-0000-4000-8000-000000000011'$q$);
reset role;
select reserve_lesson_video('00000000-0000-4000-8000-000000000012','00000000-0000-4000-8000-000000000001','2020-01-01','00000000-0000-4000-8000-000000000023','00000000-0000-4000-8000-000000000033','abandoned.mp4',1000000000);
